79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		r := jobRecord{
149			Version: recordVersion,
150	
151			ID:            j.id,
152			Submitter:     j.submitter,
153			RequestID:     j.requestID,
154			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
155			Seed:          j.seed,
156			Values:        append([]int64(nil), j.values...),
157			HasDependency: len(j.dependencies) > 0,
158			DependencyID:  depID(j),
159			Dependencies:  append([]uint64(nil), j.dependencies...),
160	
161			QueuedAt:      j.queuedAt,
162			StartedAt:     j.startedAt,
163			FinishedAt:    j.finishedAt,
164			Status:        j.status,
165			FailureReason: j.failureReason,
166			BlockerID:     j.blockerID,
167	
168			EffectiveValues: append([]int64(nil), j.effectiveValues...),
169			Archive:         j.archive,
170		}
171		return json.MarshalIndent(&r, "", "  ")
172	}
173	
174	// depID 返回首个直接上游作业号（无依赖时为 0）。
175	func depID(j *storedJob) uint64 {
176		if len(j.dependencies) == 0 {
177			return 0
178		}
179		return j.dependencies[0]
180	}
181	
182	// persist 在已持锁的情况下原子写一条作业记录。
183	func (s *Store) persist(j *storedJob) error {
184		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
185		if s.persistFault != nil {
186			if err := s.persistFault(j); err != nil {
187				return err
188			}
189		}
190		data, err := encodeRecord(j)
191		if err != nil {
192			return err
193		}
194		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
195	}
196	
197	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
198	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
199	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
200		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
201		if err != nil {
202			return err
203		}
204		tmpName := tmp.Name()
205		cleanup := true
206		defer func() {
207			if cleanup {
208				_ = os.Remove(tmpName)
209			}
210		}()
211	
212		if _, err := tmp.Write(data); err != nil {
213			_ = tmp.Close()
214			return err
215		}
216		if err := tmp.Sync(); err != nil {
217			_ = tmp.Close()
218			return err
219		}
220		if err := tmp.Close(); err != nil {
221			return err
222		}
223		if err := os.Chmod(tmpName, perm); err != nil {
224			return err
225		}
226		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
227			return err
228		}
229		cleanup = false
230		syncDir(dir)
231		return nil
232	}
233	
234	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
235	func syncDir(dir string) {
236		if d, err := os.Open(dir); err == nil {
237			_ = d.Sync()
238			_ = d.Close()
239		}
240	}
241	
242	// loadDir 扫描目录中的全部作业记录并重建内存索引。
243	//
244	// 恢复规则：
245	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
246	//   - 成功记录缺少归档、校验值对不上，依赖列表重复引用同一直接上游作业号，
247	//     或直接上游作业号不小于本作业号（引用自己或后来作业，违反提交时的
248	//     先后关系规则），实际输入与原始参数或直接依赖数量不对应，或归档数值
249	//     结果与有效输入按计算规则应得的结果不符时，fail-closed 地标记为失败，
250	//     维持“成功必有完整归档”的不变量；
251	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
252	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
253	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
254	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
255	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
256	//     保持 0。排队记录的依赖列表重复引用同一作业号，或引用作业号不小于
257	//     自己的作业（自己/后来作业），同样在恢复时直接判失败（BlockerID 为
258	//     0），不再等待或开始计算；仍在排队的其他作业在同一趟升序扫描中按
259	//     既有依赖规则级联失败。
260	func loadDir(dir string) ([]*storedJob, uint64, error) {
261		entries, err := os.ReadDir(dir)
262		if err != nil {
263			return nil, 0, err
264		}
265		var jobs []*storedJob
266		var maxID uint64
267		for _, e := range entries {
268			name := e.Name()
269			if e.IsDir() {
270				continue
271			}
272			// 清理上一进程崩溃时可能残留的原子写临时文件。
273			if strings.HasPrefix(name, ".tmp-") {
274				_ = os.Remove(filepath.Join(dir, name))
275				continue
276			}
277			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
278				continue
279			}
280			path := filepath.Join(dir, name)
281			data, err := os.ReadFile(path)
282			if err != nil {
283				return nil, 0, err
284			}
285			var r jobRecord
286			if err := json.Unmarshal(data, &r); err != nil {
287				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
288			}
289			if r.Version != recordVersion {
290				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
291			}
292			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
293			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
294			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
295			if err != nil {
296				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
297			}
298			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
299			// 与归档中的参数逐字节一致。
300			if r.Archive != nil {
301				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
302				if aErr != nil {
303					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
304				}
305				r.Archive.Submitter = aSub
306				r.Archive.RequestID = aReq
307			}
308			switch r.Status {
309			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
310			default:
311				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
312			}
313			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
314			// 恢复为只含一个作业号的列表（语义与提交时一致）。
315			deps := append([]uint64(nil), r.Dependencies...)
316			if len(deps) == 0 && r.HasDependency {
317				deps = []uint64{r.DependencyID}
318			}
319			j := &storedJob{
320				id:           r.ID,
321				submitter:    submitter,
322				requestID:    requestID,
323				seed:         r.Seed,
324				values:       append([]int64(nil), r.Values...),
325				dependencies: deps,
326	
327				queuedAt:   r.QueuedAt,
328				startedAt:  r.StartedAt,
329				finishedAt: r.FinishedAt,
330	
331				status:        r.Status,
332				failureReason: r.FailureReason,
333				blockerID:     r.BlockerID,
334	
335				effectiveValues: append([]int64(nil), r.EffectiveValues...),
336				archive:         r.Archive,
337			}
338			if j.status == StatusRunning {
339				failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
340			}
341			if j.status == StatusSucceeded {
342				// 除完整性外，还必须满足三条独立的对应/复算规则：
343				//  0. 依赖列表自身合法，按以下顺序检查：
344				//     a. 同一直接上游作业号不能出现两次（相邻或隔着其他上游都算）。
345				//        这与提交时 validateDependenciesLocked 的唯一性要求一致；
346				//        旧版本或被改动的记录可能保存了重复引用，此时即使追加值、
347				//        总和、平方和、摘要、日志与校验值全部自洽，也不能当作合法
348				//        成功归档（重复引用会把同一上游总和追加两次）。
349				//     b. 每个直接上游作业号都必须严格小于本作业号。正常提交只能引用
350				//        已经存在的作业，作业号又按接受先后递增，所以引用自己或引用
351				//        后来作业都不可能通过提交校验；旧版本或被改动的记录可能保存
352				//        这种依赖，即使被引用作业确实存在且成功、本作业的追加值、总和、
353				//        平方和、摘要、日志与校验值全部自洽，也不能接受。已因重复
354				//        依赖判失败的记录保留重复失败说明，不再改写。
355				//     两项都属于本作业记录自身有误，在任何上游可用性核对之前判定，
356				//     BlockerID 为 0，不把被引用的有效上游判成失败。
357				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
358				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
359				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
360				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
361				//     原始参数与依赖数量才能识别。
362				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
363				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
364				//     输入复算才能识别。
365				// 任一不符合都按损坏归档处理。第四条规则——追加部分逐项等于各
366				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
367				// 在排序后的第二趟扫描中执行。
368				var invalidReason string
369				if dupID, dup := duplicateDependency(j); dup {
370					invalidReason = duplicateDependencyReason(dupID)
371				} else if badID, bad := firstIllegalOrderingDependency(j); bad {
372					invalidReason = illegalOrderingDependencyReason(badID, j.id)
373				} else if !archiveIntact(j) {
374					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
375				} else if !effectiveInputsCorrespond(j) {
376					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
377				} else if !archiveResultsValid(j) {
378					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
379				}
380				if invalidReason != "" {
381					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
382					failRestoredJob(dir, j, invalidReason, 0)
383				}
384			}
385			jobs = append(jobs, j)
386			if j.id > maxID {
387				maxID = j.id
388			}
389		}
390		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
391		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
392		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
393		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
394		// 依赖链在单趟级联扫描中漏掉失败传播）。
395		sort.Slice(jobs, func(a, b int) bool {
396			return jobs[a].id < jobs[b].id
397		})
398		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
399		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
400		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
401		// 不会在每经过一个已归档的中间作业时重新起算。
402		//
403		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
404		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
405		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
406		// BlockerID 才保持 0。
407		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
408		//   - 排队记录：先检查依赖列表自身是否合法——重复引用同一作业号，或
409		//     引用作业号不小于自己的作业（自己或后来作业），都属本作业自身有误，
410		//     BlockerID 为 0，立即失败且重复检查优先（保留现有重复失败说明）；
411		//     再按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，或记录
412		//     缺失），立即级联失败，不再等待。
413		//
414		// 依赖列表自身不合法属于记录自身问题，先于一切上游可用性判断：即使被引用
415		// 的上游仍在排队或确实存在且成功，不合法记录也要立即失败；而等待该记录
416		// 结果的下游则按既有规则把它当作失败上游级联，根因就是这份记录自身。
417		byID := make(map[uint64]*storedJob, len(jobs))
418		for _, j := range jobs {
419			byID[j.id] = j
420		}
421		for _, j := range jobs {
422			if len(j.dependencies) == 0 {
423				continue
424			}
425			switch j.status {
426			case StatusSucceeded:
427				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
428				// 未保持带完整归档的成功状态）。
429				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
430				if unavailable {
431					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
432					// 直接上游记录缺失时以缺失的作业号本身作为根因。
433					root := blockerRoot(dep, directID)
434					failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
435					continue
436				}
437				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
438				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
439				// 失败或归因给它，BlockerID 保持 0。
440				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
441					failRestoredJob(dir, j, detail, 0)
442				}
443			case StatusQueued:
444				// 排队记录的依赖列表同样不能重复引用同一作业号：这属于本作业记录
445				// 自身有误，在选取不可用上游之前直接判失败——不能开始计算，也不能
446				// 把同一上游总和追加两次后继续。BlockerID 保持 0，不把被重复引用
447				// 且原本有效的上游改成失败。
448				if dupID, dup := duplicateDependency(j); dup {
449					failRestoredJob(dir, j, duplicateDependencyReason(dupID), 0)
450					continue
451				}
452				// 依赖先后关系同样是记录自身问题：直接上游作业号必须严格小于本作业号，
453				// 引用自己或后来作业即使被引用者存在且成功也不能接受，不能开始计算或
454				// 继续等待。排在重复检查之后，已因重复依赖判失败的记录保留现有说明。
455				if badID, bad := firstIllegalOrderingDependency(j); bad {
456					failRestoredJob(dir, j, illegalOrderingDependencyReason(badID, j.id), 0)
457					continue
458				}
459				// 按保存的依赖顺序选取最靠前的不可用上游；其他上游作业号更小
460				// 或失败原因不同都不能改变这个选择。
461				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
462				if !blocked {
463					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
464				}
465				root := blockerRoot(direct, directID)
466				if direct == nil {
467					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
468					// 以缺失的作业号作为根因，并明确说明结果无法使用。
469					failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
470					continue
471				}
472				failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
473			}
474		}
475		return jobs, maxID, nil
476	}
477	
478	// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
479	// 供五类恢复失败共用（调用顺序即各类判定的既有先后）：
480	//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
481	//   - 原标为成功、但归档完整性、依赖列表唯一性或先后关系、实际输入对应
482	//     关系或数值结果不符规则的作业：本作业自身归档校验失败（第一趟记录
483	//     扫描，BlockerID 恒 0；唯一性检查先于先后关系检查）；
484	//   - 排队记录的依赖列表重复引用同一作业号：本作业记录自身有误（第二趟升序
485	//     扫描，BlockerID 恒 0，先于上游可用性判断）；
486	//   - 排队记录引用作业号不小于自己的作业（自己/后来作业）：本作业记录自身
487	//     有误（第二趟升序扫描，BlockerID 恒 0，在重复检查之后、上游可用性
488	//     判断之前）；
489	//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
490	//     BlockerID 由调用方按 blocker.go 的归因规则给出。
491	//
492	// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
493	// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
494	// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
495	// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
496	// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
497	// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
498	// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
499	func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
500		j.status = StatusFailed
501		j.failureReason = reason
502		j.blockerID = blocker
503		if j.finishedAt.IsZero() {
504			j.finishedAt = time.Now().UTC()
505		}
506		j.effectiveValues = nil
507		j.archive = nil
508		if data, err := encodeRecord(j); err == nil {
509			_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
510		}
511	}
512	
513	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
514	func archiveIntact(j *storedJob) bool {
515		a := j.archive
516		if a == nil {
517			return false
518		}
519		// 归档中的原始参数必须与记录顶层字段一致。
520		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
521			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
522			return false
523		}
524		if a.HasDependency && a.DependencyID != depID(j) {
525			return false
526		}
527		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
528		// 由单依赖字段推导后再比较。
529		aDeps := append([]uint64(nil), a.Dependencies...)
530		if len(aDeps) == 0 && a.HasDependency {
531			aDeps = []uint64{a.DependencyID}
532		}
533		if len(aDeps) != len(j.dependencies) {
534			return false
535		}
536		for i := range j.dependencies {
537			if aDeps[i] != j.dependencies[i] {
538				return false
539			}
540		}
541		if len(a.Values) != len(j.values) {
542			return false
543		}
544		for i := range j.values {
545			if a.Values[i] != j.values[i] {
546				return false
547			}
548		}
549		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
550			return false
551		}
552		for i := range j.effectiveValues {
553			if j.effectiveValues[i] != a.EffectiveValues[i] {
554				return false
555			}
556		}
557		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
558			return false
559		}
560		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
561			return false
562		}
563		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
564			return false
565		}
566		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
567			return false
568		}
569		return true
570	}
571	
572	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
573	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
574	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
575	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
576	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
577	// （包括回绕后的值）都不能作为有效成功结果保留。
578	//
579	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
580	func archiveResultsValid(j *storedJob) bool {
581		a := j.archive
582		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
583		if !ok {
584			return false
585		}
586		return a.Sum == sum && a.SumOfSquares == sumSquares
587	}
588	
589	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
590	// 参数、直接依赖数量之间的对应关系：
591	//   - 原始序列必须非空；
592	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
593	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
594	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
595	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
596	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
597	//     能多出未记录的输入。
598	//
599	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
600	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
601	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
602	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
603	//
604	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
605	// 副本与顶层一致）。
606	func effectiveInputsCorrespond(j *storedJob) bool {
607		n := len(j.values)
608		if n == 0 {
609			return false
610		}
611		if len(j.effectiveValues) != n+len(j.dependencies) {
612			return false
613		}
614		for i := 0; i < n; i++ {
615			if j.effectiveValues[i] != j.values[i] {
616				return false
617			}
618		}
619		return true
620	}
621

