57	func TestMultiDependencyRejectsInvalidList(t *testing.T) {
58		s, _ := openTestStore(t)
59		u := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u", Values: []int64{1}})
60		waitStatus(t, s, u.ID, StatusSucceeded)
61	
62		cases := []struct {
63			name string
64			deps []uint64
65			want error
66		}{
67			{"zero", []uint64{0}, ErrInvalidDependency},
68			{"duplicate", []uint64{u.ID, u.ID}, ErrInvalidDependency},
69			{"missing", []uint64{u.ID, 999}, ErrDependencyNotFound},
70		}
71		for _, c := range cases {
72			_, err := s.Submit(SubmitRequest{
73				Submitter: "a", RequestID: "bad-" + c.name, Values: []int64{1},
74				Dependencies: c.deps,
75			})
76			if !errors.Is(err, c.want) {
77				t.Fatalf("%s: err=%v want %v", c.name, err, c.want)
78			}
79		}
80		// 单依赖方式与非空列表同时启用 → 拒绝。
81		_, err := s.Submit(SubmitRequest{
82			Submitter: "a", RequestID: "both", Values: []int64{1},
83			HasDependency: true, DependencyID: u.ID, Dependencies: []uint64{u.ID},
84		})
85		if !errors.Is(err, ErrInvalidDependency) {
86			t.Fatalf("both modes: err=%v want ErrInvalidDependency", err)
87		}
88		// 拒绝不产生记录，也不占用幂等请求号：同号合法提交仍创建新作业。
89		if got, _ := s.List("a", time.Time{}, time.Time{}); len(got) != 1 {
90			t.Fatalf("rejected submits left records: %d", len(got))
91		}
92		ok := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "both", Values: []int64{7}})
93		if ok.ID == u.ID {
94			t.Fatal("rejected submit consumed the idempotency request number")
95		}
96		waitStatus(t, s, ok.ID, StatusSucceeded)
97	}
